fn debug_matches_nightly<A: core::fmt::Debug, B: core::fmt::Debug>(
    #[case] ours: A,
    #[case] nightly: B,
) {
    assert_eq!(format!("{ours:?}"), format!("{nightly:?}"), "{{:?}}");
    assert_eq!(format!("{ours:+?}"), format!("{nightly:+?}"), "{{:+?}}");
    assert_eq!(format!("{ours:#?}"), format!("{nightly:#?}"), "{{:#?}}");
    assert_eq!(format!("{ours:12?}"), format!("{nightly:12?}"), "{{:12?}}");
    assert_eq!(
        format!("{ours:<12?}"),
        format!("{nightly:<12?}"),
        "{{:<12?}}"
    );
    assert_eq!(
        format!("{ours:^12?}"),
        format!("{nightly:^12?}"),
        "{{:^12?}}"
    );
    assert_eq!(
        format!("{ours:>12?}"),
        format!("{nightly:>12?}"),
        "{{:>12?}}"
    );
    assert_eq!(
        format!("{ours:012?}"),
        format!("{nightly:012?}"),
        "{{:012?}}"
    );
    assert_eq!(format!("{ours:.3?}"), format!("{nightly:.3?}"), "{{:.3?}}");
    assert_eq!(
        format!("{ours:+.3?}"),
        format!("{nightly:+.3?}"),
        "{{:+.3?}}"
    );
    assert_eq!(
        format!("{ours:12.3?}"),
        format!("{nightly:12.3?}"),
        "{{:12.3?}}"
    );
}
